import type { LanguageCode } from "@cv-snap/shared";

/**
 * GDPR consent clause (klauzula RODO, FR-15). The text always comes verbatim from the user's
 * settings; it is never generated by Claude. The settings editor is bolt 012.
 */
export type GdprClauseMode = "polishAdsOnly" | "always" | "never";

export const DEFAULT_GDPR_CLAUSE_MODE: GdprClauseMode = "polishAdsOnly";

/** Standard Polish recruitment consent wording; the user replaces the bracketed company name. */
export const DEFAULT_GDPR_CLAUSE_PL =
  "Wyrażam zgodę na przetwarzanie moich danych osobowych przez [nazwa firmy] w celu prowadzenia " +
  "rekrutacji na aplikowane przeze mnie stanowisko.";

export const DEFAULT_GDPR_CLAUSE_EN =
  "I consent to the processing of my personal data by [company name] for the purpose of the " +
  "recruitment process for the position I am applying for.";

export interface GdprClauseSettings {
  mode: GdprClauseMode;
  /** Used when the CV is written in Polish. */
  textPl: string;
  /** Used for every other output language. */
  textEn: string;
}

export const DEFAULT_GDPR_CLAUSE_SETTINGS: GdprClauseSettings = {
  mode: DEFAULT_GDPR_CLAUSE_MODE,
  textPl: DEFAULT_GDPR_CLAUSE_PL,
  textEn: DEFAULT_GDPR_CLAUSE_EN,
};

/**
 * Whether the clause belongs on this CV. "Polish ads only" looks at the ad, not the CV language.
 * When the ad's language is undecidable (`null`), the decided output language stands in for it:
 * that is the same fallback chain the CV text uses (override > ad > profile, `decideOutputLanguage`).
 */
export function shouldIncludeClause(
  mode: GdprClauseMode,
  adLanguage: LanguageCode | null,
  outputLanguage: LanguageCode,
): boolean {
  if (mode === "always") return true;
  if (mode === "never") return false;
  return (adLanguage ?? outputLanguage) === "pl";
}

/**
 * The clause to print, verbatim from settings, or null. The text follows the CV's output language
 * (Polish CV → Polish clause); blank settings text means no clause.
 */
export function selectClause(
  settings: GdprClauseSettings,
  adLanguage: LanguageCode | null,
  outputLanguage: LanguageCode,
): string | null {
  if (!shouldIncludeClause(settings.mode, adLanguage, outputLanguage)) return null;
  const text = outputLanguage === "pl" ? settings.textPl : settings.textEn;
  return text.trim().length > 0 ? text : null;
}
